// Package camdet detects whether USB cameras are currently in use on a Linux
// system by reading the kernel's V4L2, sysfs, and procfs interfaces directly.
//
// A camera is considered "in use" when any process holds one of its
// /dev/videoN nodes open. Only cameras whose sysfs path traces to a USB bus are
// reported. Reading another user's /proc/<pid>/fd requires root; without it the
// scan still returns what it can see and reports reduced visibility via
// Result.FullVisibility.
//
// Microphone detection is optional and depends on the sound server (PipeWire
// for desktops, raw ALSA for headless). See DetectMicInUse().
package camdet

import (
	"encoding/json"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"strings"
)

// Mic represents an audio capture device and its current use state.
type Mic struct {
	Name    string `json:"name"`    // device name from PipeWire/ALSA
	Device  string `json:"device"`  // device identifier (PipeWire node name or ALSA subdevice path)
	InUse   bool   `json:"inUse"`   // true if any stream is capturing
	Users   []User `json:"users"`   // processes capturing audio; may be partial
	Backend string `json:"backend"` // "pipewire" or "alsa"
}

// User identifies a process capturing audio.
type User struct {
	PID  int    `json:"pid"`
	Name string `json:"name"` // from /proc/<pid>/comm
}

// hasPipeWire returns true if PipeWire or PulseAudio appears to be running.
func hasPipeWire() bool {
	// Check for pipewire or pulseaudio processes
	commands := []string{"pipewire", "wireplumber", "pulseaudio"}
	for _, cmd := range commands {
		if _, err := exec.LookPath(cmd); err == nil {
			if err := exec.Command("pgrep", "-x", cmd).Run(); err == nil {
				return true
			}
		}
	}
	return false
}

// detectMicPipeWire queries PipeWire for active audio capture streams.
// It returns mic state and users, or an error if pw-dump fails.
func detectMicPipeWire() ([]Mic, error) {
	cmd := exec.Command("pw-dump")
	output, err := cmd.Output()
	if err != nil {
		return nil, fmt.Errorf("pw-dump failed: %w", err)
	}

	// Parse JSON to find running Stream/Input/Audio nodes
	type Props struct {
		MediaClass       string `json:"media.class"`
		NodeName         string `json:"node.name"`
		AppName          string `json:"application.name"`
		AppProcessBinary string `json:"application.process.binary"`
		AppProcessID     int    `json:"application.process.id"`
		DeviceAPI        string `json:"device.api"`
		BlueprintName    string `json:"api.bluez5.profile"`
	}

	type Info struct {
		State string `json:"state"`
		Props Props  `json:"props"`
	}

	type Node struct {
		Type string `json:"type"`
		Info Info   `json:"info"`
	}

	var nodes []Node
	if err := json.Unmarshal(output, &nodes); err != nil {
		return nil, fmt.Errorf("parsing pw-dump JSON: %w", err)
	}

	// Find running Stream/Input/Audio nodes (application capture streams)
	var mics []Mic
	var users []User
	seenDevices := make(map[string]bool)

	for _, node := range nodes {
		if node.Type != "PipeWire:Interface:Node" {
			continue
		}

		// We care about Stream/Input/Audio (application capture) or Audio/Source (device)
		if node.Info.State != "running" {
			continue
		}

		mc := node.Info.Props.MediaClass
		if mc == "Stream/Input/Audio" {
			// Application is capturing
			if node.Info.Props.AppProcessID > 0 {
				users = append(users, User{
					PID:  node.Info.Props.AppProcessID,
					Name: node.Info.Props.AppProcessBinary,
				})
			}

			// Find the underlying source device for name
			if !seenDevices[node.Info.Props.NodeName] {
				seenDevices[node.Info.Props.NodeName] = true
				mics = append(mics, Mic{
					Name:    node.Info.Props.NodeName,
					Device:  node.Info.Props.NodeName,
					InUse:   true,
					Users:   users,
					Backend: "pipewire",
				})
			}
		} else if mc == "Audio/Source" && node.Info.Props.DeviceAPI == "bluez5" {
			// Bluetooth headset in HSP/HFP mode (has mic)
			if !seenDevices[node.Info.Props.NodeName] {
				seenDevices[node.Info.Props.NodeName] = true
				mics = append(mics, Mic{
					Name:    node.Info.Props.NodeName,
					Device:  node.Info.Props.NodeName,
					InUse:   true,
					Users:   users,
					Backend: "pipewire",
				})
			}
		}
	}

	return mics, nil
}

// detectMicALSA scans ALSA capture devices via /proc/asound.
// This is the fallback for headless/embedded systems without PipeWire.
func detectMicALSA() ([]Mic, error) {
	// Scan /proc/asound/card*/pcm*c/sub*/status
	procRoot := "/proc/asound"
	entries, err := os.ReadDir(procRoot)
	if err != nil {
		// No ALSA cards present
		return []Mic{}, nil
	}

	var mics []Mic

	for _, entry := range entries {
		if !entry.IsDir() || !strings.HasPrefix(entry.Name(), "card") {
			continue
		}
		cardPath := filepath.Join(procRoot, entry.Name())
		subEntries, err := os.ReadDir(cardPath)
		if err != nil {
			continue
		}

		for _, sub := range subEntries {
			statusPath := filepath.Join(cardPath, sub.Name(), "status")
			if !strings.HasSuffix(sub.Name(), "c") {
				continue
			}
			data, err := os.ReadFile(statusPath)
			if err != nil {
				continue
			}

			status := strings.TrimSpace(string(data))
			if strings.Contains(status, "state: RUNNING") {
				// Extract owner PID from status
				lines := strings.Split(status, "\n")
				var pid int
				for _, line := range lines {
					if strings.HasPrefix(line, "owner_pid:") {
						fmt.Sscanf(line, "owner_pid: %d", &pid)
						break
					}
				}

				// Try to get process name
				name := ""
				if pid > 0 {
					commPath := filepath.Join("/proc", fmt.Sprintf("%d", pid), "comm")
					if commData, err := os.ReadFile(commPath); err == nil {
						name = strings.TrimSpace(string(commData))
					}
				}

				mics = append(mics, Mic{
					Name:    fmt.Sprintf("%s - %s", entry.Name(), sub.Name()),
					Device:  statusPath,
					InUse:   true,
					Users:   []User{{PID: pid, Name: name}},
					Backend: "alsa",
				})
			}
		}
	}

	return mics, nil
}

// DetectMicInUse scans for active audio capture (microphone use).
// It prefers PipeWire on desktop systems, falling back to raw ALSA on headless systems.
// Returns mic devices and whether any are in use.
func DetectMicInUse() ([]Mic, error) {
	// Try PipeWire first (desktop)
	if hasPipeWire() {
		mics, err := detectMicPipeWire()
		if err != nil {
			// Fall back to ALSA if PipeWire fails
			return detectMicALSA()
		}
		return mics, nil
	}

	// Fall back to ALSA (headless/embedded)
	return detectMicALSA()
}

// MicResult wraps camera and microphone detection results.
type MicResult struct {
	*Result
	Mics []Mic `json:"mics"`
}

// DetectWithMic returns both camera and microphone detection results.
func DetectWithMic() (*MicResult, error) {
	camRes, err := Detect()
	if err != nil {
		return nil, err
	}

	mics, err := DetectMicInUse()
	if err != nil {
		// Don't fail the whole scan if mic detection fails
		mics = []Mic{}
	}

	return &MicResult{
		Result: camRes,
		Mics:   mics,
	}, nil
}

// Package camdet detects whether USB cameras are currently in use on a Linux
// system by reading the kernel's V4L2, sysfs, and procfs interfaces directly.
//
// A camera is considered "in use" when any process holds one of its
// /dev/videoN nodes open. Only cameras whose sysfs path traces to a USB bus are
// reported. Reading another user's /proc/<pid>/fd requires root; without it the
// scan still returns what it can see and reports reduced visibility via
// Result.FullVisibility.
package camdet

import (
	"sort"
)

// Camera is one physical USB camera, aggregating all of its V4L2 device nodes.
type Camera struct {
	Name      string    `json:"name"`      // model name from sysfs (e.g. "HD Pro Webcam C920")
	USBPath   string    `json:"usbPath"`   // physical-device key, e.g. "/sys/bus/usb/devices/1-2"
	VendorID  string    `json:"vendorId"`  // 4-hex USB vendor id, e.g. "046d"
	ProductID string    `json:"productId"` // 4-hex USB product id, e.g. "082d"
	Serial    string    `json:"serial"`    // may be empty if not exposed
	Nodes     []string  `json:"nodes"`     // e.g. ["/dev/video0", "/dev/video1"]
	InUse     bool      `json:"inUse"`     // true if any node is held open by a process
	Users     []Process `json:"users"`     // processes holding a node open; may be partial
}

// Process identifies a process holding a camera node open.
type Process struct {
	PID  int    `json:"pid"`
	Name string `json:"name"` // from /proc/<pid>/comm
	Node string `json:"node"` // which /dev/videoN this process has open
}

// Result is a full detection snapshot.
type Result struct {
	Cameras []Camera `json:"cameras"`
	// FullVisibility is false if some /proc entries were unreadable due to
	// permissions (i.e. the process is not running as root), meaning per-camera
	// Users lists may be incomplete.
	FullVisibility bool `json:"fullVisibility"`
}

// Detect scans the live system and returns the current snapshot of USB cameras.
func Detect() (*Result, error) {
	return detect("/")
}

// detect performs the scan against the given filesystem root. Production uses
// root "/"; tests point it at a synthetic sysfs/proc tree.
func detect(root string) (*Result, error) {
	nodes, err := enumerate(root)
	if err != nil {
		return nil, err
	}

	// Group nodes by physical USB device.
	byUSB := make(map[string]*Camera)
	var order []string
	nodeSet := make(map[string]bool)
	for _, n := range nodes {
		nodeSet[n.devNode] = true
		cam, ok := byUSB[n.usbPath]
		if !ok {
			cam = &Camera{
				Name:      n.name,
				USBPath:   n.usbPath,
				VendorID:  n.vendorID,
				ProductID: n.productID,
				Serial:    n.serial,
			}
			byUSB[n.usbPath] = cam
			order = append(order, n.usbPath)
		}
		cam.Nodes = append(cam.Nodes, n.devNode)
	}

	openByNode, fullVisibility, err := scanOpen(root, nodeSet)
	if err != nil {
		return nil, err
	}

	// Attribute open handles to their owning camera.
	for _, cam := range byUSB {
		sort.Strings(cam.Nodes)
		for _, node := range cam.Nodes {
			for _, proc := range openByNode[node] {
				cam.InUse = true
				cam.Users = append(cam.Users, proc)
			}
		}
		sort.Slice(cam.Users, func(i, j int) bool {
			if cam.Users[i].PID != cam.Users[j].PID {
				return cam.Users[i].PID < cam.Users[j].PID
			}
			return cam.Users[i].Node < cam.Users[j].Node
		})
	}

	// Emit cameras in a deterministic order (by USB path).
	sort.Strings(order)
	cameras := make([]Camera, 0, len(order))
	for _, usbPath := range order {
		cameras = append(cameras, *byUSB[usbPath])
	}

	return &Result{Cameras: cameras, FullVisibility: fullVisibility}, nil
}

// Command gocamdet reports which USB cameras are currently in use on this
// Linux system. It prints a human-readable table by default, or JSON with
// --json, and sets its exit code so it can be used in shell scripts:
//
//	0  no camera in use
//	1  at least one camera in use
//	2  error
package main

import (
	"encoding/json"
	"flag"
	"fmt"
	"os"
	"strconv"
	"strings"
	"text/tabwriter"
	"time"

	"github.com/gherlein/gocamdet"
)

const (
	exitNoneInUse = 0
	exitInUse     = 1
	exitError     = 2
)

func main() {
	os.Exit(run())
}

func run() int {
	asJSON := flag.Bool("json", false, "emit the result as JSON on stdout")
	watch := flag.Bool("watch", false, "run continuously, firing a hook on camera/mic on/off transitions")
	interval := flag.Duration("interval", 2*time.Second, "poll interval in --watch mode")
	script := flag.String("script", "", "hook script run on each transition in --watch mode (receives on|off)")
	scriptTimeout := flag.Duration("script-timeout", 30*time.Second, "maximum run time for a --watch hook script")
	flag.Parse()

	if *watch {
		return runWatch(*script, *interval, *scriptTimeout, *asJSON)
	}

	result, err := camdet.DetectWithMic()
	if err != nil {
		fmt.Fprintf(os.Stderr, "gocamdet: %v\n", err)
		return exitError
	}

	if !result.FullVisibility {
		fmt.Fprintln(os.Stderr, "gocamdet: reduced visibility — not all processes could be inspected; re-run with sudo for complete results")
	}

	if *asJSON {
		if err := emitJSON(result); err != nil {
			fmt.Fprintf(os.Stderr, "gocamdet: %v\n", err)
			return exitError
		}
	} else {
		emitTable(result)
	}

	return exitCode(result)
}

func emitJSON(result *camdet.Result) error {
	enc := json.NewEncoder(os.Stdout)
	enc.SetIndent("", "  ")
	return enc.Encode(result)
}

func emitTable(result *camdet.Result) {
	if len(result.Cameras) == 0 && len(result.Mics) == 0 {
		fmt.Println("No USB cameras or microphones found.")
		return
	}

	writer := tabwriter.NewWriter(os.Stdout, 0, 4, 2, ' ', 0)
	fmt.Fprintln(writer, "DEVICE\tTYPE\tNODES\tIN USE\tUSED BY")

	// Emit cameras
	for _, cam := range result.Cameras {
		fmt.Fprintf(writer, "%s\tcamera\t%s\t%s\t%s\n",
			orDash(cam.Name),
			strings.Join(cam.Nodes, ","),
			yesNo(cam.InUse),
			formatUsers(cam.Users),
		)
	}

	// Emit microphones
	for _, mic := range result.Mics {
		fmt.Fprintf(writer, "%s\tmic\t%s\t%s\t%s\n",
			orDash(mic.Name),
			mic.Device,
			yesNo(mic.InUse),
			formatMicUsers(mic.Users),
		)
	}
	_ = writer.Flush()
}

func formatMicUsers(users []camdet.User) string {
	if len(users) == 0 {
		return "-"
	}
	parts := make([]string, 0, len(users))
	for _, u := range users {
		parts = append(parts, fmt.Sprintf("%s(%d)", u.Name, u.PID))
	}
	return strings.Join(parts, ",")
}

func exitCode(result *camdet.Result) int {
	for _, cam := range result.Cameras {
		if cam.InUse {
			return exitInUse
		}
	}
	for _, mic := range result.Mics {
		if mic.InUse {
			return exitInUse
		}
	}
	return exitNoneInUse
}

func yesNo(b bool) string {
	if b {
		return "yes"
	}
	return "no"
}

func orDash(s string) string {
	if s == "" {
		return "-"
	}
	return s
}

package camdet

import (
	"os"
	"path/filepath"
	"strconv"
	"testing"
)

// fixture builds a synthetic filesystem root with a sysfs and proc tree so the
// scan can be exercised without root privileges or real hardware.
type fixture struct {
	t    *testing.T
	root string
}

func newFixture(t *testing.T) *fixture {
	t.Helper()
	return &fixture{t: t, root: t.TempDir()}
}

// addUSBCamera creates a USB device directory with the given identity and one
// video4linux node per name in nodes (all under the same physical device, so
// they group together). It mirrors real sysfs relative symlinks.
func (f *fixture) addUSBCamera(deviceKey, vendor, product, name, serial string, nodes ...string) {
	f.t.Helper()
	usbDir := filepath.Join(f.root, "sys", "devices", "usbtree", deviceKey)
	ifaceDir := filepath.Join(usbDir, deviceKey+":1.0")
	mustMkdir(f.t, ifaceDir)
	mustWrite(f.t, filepath.Join(usbDir, "idVendor"), vendor+"\n")
	mustWrite(f.t, filepath.Join(usbDir, "idProduct"), product+"\n")
	if product != "" {
		mustWrite(f.t, filepath.Join(usbDir, "product"), name+"\n")
	}
	if serial != "" {
		mustWrite(f.t, filepath.Join(usbDir, "serial"), serial+"\n")
	}

	classDir := filepath.Join(f.root, "sys", "class", "video4linux")
	mustMkdir(f.t, classDir)
	for _, node := range nodes {
		nodeDir := filepath.Join(ifaceDir, "video4linux", node)
		mustMkdir(f.t, nodeDir)
		rel, err := filepath.Rel(classDir, nodeDir)
		if err != nil {
			f.t.Fatalf("computing relative link: %v", err)
		}
		if err := os.Symlink(rel, filepath.Join(classDir, node)); err != nil {
			f.t.Fatalf("symlinking class node: %v", err)
		}
	}
}

// addNonUSBCamera creates a video4linux node on a non-USB (platform) path.
func (f *fixture) addNonUSBCamera(node string) {
	f.t.Helper()
	nodeDir := filepath.Join(f.root, "sys", "devices", "platform", "soc", "camera", "video4linux", node)
	mustMkdir(f.t, nodeDir)
	classDir := filepath.Join(f.root, "sys", "class", "video4linux")
	mustMkdir(f.t, classDir)
	rel, err := filepath.Rel(classDir, nodeDir)
	if err != nil {
		f.t.Fatalf("computing relative link: %v", err)
	}
	if err := os.Symlink(rel, filepath.Join(classDir, node)); err != nil {
		f.t.Fatalf("symlinking class node: %v", err)
	}
}

// addProcessUsing creates a /proc/<pid> entry whose fd points at devNode.
func (f *fixture) addProcessUsing(pid int, comm, devNode string) {
	f.t.Helper()
	fdDir := filepath.Join(f.root, "proc", strconv.Itoa(pid), "fd")
	mustMkdir(f.t, fdDir)
	mustWrite(f.t, filepath.Join(f.root, "proc", strconv.Itoa(pid), "comm"), comm+"\n")
	if err := os.Symlink(devNode, filepath.Join(fdDir, "3")); err != nil {
		f.t.Fatalf("symlinking fd: %v", err)
	}
}

// addUnreadableProcess creates a /proc/<pid>/fd directory that cannot be read,
// simulating another user's process when not running as root.
func (f *fixture) addUnreadableProcess(pid int) {
	f.t.Helper()
	fdDir := filepath.Join(f.root, "proc", strconv.Itoa(pid), "fd")
	mustMkdir(f.t, fdDir)
	if err := os.Chmod(fdDir, 0o000); err != nil {
		f.t.Fatalf("chmod fd dir: %v", err)
	}
	f.t.Cleanup(func() { _ = os.Chmod(fdDir, 0o755) })
}

// ensureProc guarantees a /proc directory exists even with no processes, since
// scanOpen treats a missing procfs as a hard error.
func (f *fixture) ensureProc() {
	f.t.Helper()
	mustMkdir(f.t, filepath.Join(f.root, "proc"))
}

func TestNoCameras(t *testing.T) {
	f := newFixture(t)
	mustMkdir(t, filepath.Join(f.root, "sys", "class", "video4linux"))
	f.ensureProc()

	res, err := detect(f.root)
	if err != nil {
		t.Fatalf("detect: %v", err)
	}
	if len(res.Cameras) != 0 {
		t.Fatalf("expected 0 cameras, got %d", len(res.Cameras))
	}
	if !res.FullVisibility {
		t.Fatalf("expected full visibility")
	}
}

func TestOneCameraIdle(t *testing.T) {
	f := newFixture(t)
	f.addUSBCamera("1-2", "046d", "082d", "HD Pro Webcam C920", "ABC123", "video0")
	f.ensureProc()

	res, err := detect(f.root)
	if err != nil {
		t.Fatalf("detect: %v", err)
	}
	if len(res.Cameras) != 1 {
		t.Fatalf("expected 1 camera, got %d", len(res.Cameras))
	}
	cam := res.Cameras[0]
	if cam.InUse {
		t.Fatalf("expected idle camera")
	}
	if cam.Name != "HD Pro Webcam C920" || cam.VendorID != "046d" || cam.ProductID != "082d" || cam.Serial != "ABC123" {
		t.Fatalf("unexpected camera identity: %+v", cam)
	}
	if len(cam.Nodes) != 1 || cam.Nodes[0] != "/dev/video0" {
		t.Fatalf("unexpected nodes: %v", cam.Nodes)
	}
}

func TestOneCameraInUse(t *testing.T) {
	f := newFixture(t)
	f.addUSBCamera("1-2", "046d", "082d", "HD Pro Webcam C920", "ABC123", "video0")
	f.addProcessUsing(1234, "zoom", "/dev/video0")

	res, err := detect(f.root)
	if err != nil {
		t.Fatalf("detect: %v", err)
	}
	cam := res.Cameras[0]
	if !cam.InUse {
		t.Fatalf("expected in-use camera")
	}
	if len(cam.Users) != 1 {
		t.Fatalf("expected 1 user, got %d", len(cam.Users))
	}
	u := cam.Users[0]
	if u.PID != 1234 || u.Name != "zoom" || u.Node != "/dev/video0" {
		t.Fatalf("unexpected user: %+v", u)
	}
}

func TestMultiNodeGrouping(t *testing.T) {
	f := newFixture(t)
	f.addUSBCamera("1-2", "046d", "082d", "HD Pro Webcam C920", "ABC123", "video0", "video1")
	f.ensureProc()

	res, err := detect(f.root)
	if err != nil {
		t.Fatalf("detect: %v", err)
	}
	if len(res.Cameras) != 1 {
		t.Fatalf("expected multi-node camera grouped into 1, got %d", len(res.Cameras))
	}
	nodes := res.Cameras[0].Nodes
	if len(nodes) != 2 || nodes[0] != "/dev/video0" || nodes[1] != "/dev/video1" {
		t.Fatalf("unexpected grouped nodes: %v", nodes)
	}
}

func TestNonUSBExcluded(t *testing.T) {
	f := newFixture(t)
	f.addUSBCamera("1-2", "046d", "082d", "HD Pro Webcam C920", "ABC123", "video0")
	f.addNonUSBCamera("video9")
	f.ensureProc()

	res, err := detect(f.root)
	if err != nil {
		t.Fatalf("detect: %v", err)
	}
	if len(res.Cameras) != 1 {
		t.Fatalf("expected non-USB device excluded, got %d cameras", len(res.Cameras))
	}
	if res.Cameras[0].USBPath == "" {
		t.Fatalf("expected the USB camera to survive")
	}
}

func TestReducedVisibility(t *testing.T) {
	f := newFixture(t)
	f.addUSBCamera("1-2", "046d", "082d", "HD Pro Webcam C920", "ABC123", "video0")
	f.addUnreadableProcess(9999)

	res, err := detect(f.root)
	if err != nil {
		t.Fatalf("detect: %v", err)
	}
	if res.FullVisibility {
		t.Fatalf("expected reduced visibility when a proc fd dir is unreadable")
	}
}

func TestTwoCamerasOneInUse(t *testing.T) {
	f := newFixture(t)
	f.addUSBCamera("1-2", "046d", "082d", "HD Pro Webcam C920", "ABC123", "video0")
	f.addUSBCamera("3-1", "1234", "5678", "Some Other Cam", "", "video2")
	f.addProcessUsing(1111, "obs", "/dev/video2")

	res, err := detect(f.root)
	if err != nil {
		t.Fatalf("detect: %v", err)
	}
	if len(res.Cameras) != 2 {
		t.Fatalf("expected 2 cameras, got %d", len(res.Cameras))
	}
	// Cameras are sorted by USB path; "1-2" sorts before "3-1".
	if res.Cameras[0].InUse {
		t.Fatalf("expected first camera idle")
	}
	if !res.Cameras[1].InUse {
		t.Fatalf("expected second camera in use")
	}
