package main

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"github.com/gherlein/gocamdet"
)

func idleResult() *camdet.Result {
	return &camdet.Result{
		Cameras: []camdet.Camera{{
			Name:      "HD Pro Webcam C920",
			VendorID:  "046d",
			ProductID: "082d",
			Nodes:     []string{"/dev/video0"},
			InUse:     false,
		}},
		FullVisibility: true,
	}
}

func inUseResult() *camdet.Result {
	return &camdet.Result{
		Cameras: []camdet.Camera{{
			Name:      "HD Pro Webcam C920",
			VendorID:  "046d",
			ProductID: "082d",
			Nodes:     []string{"/dev/video0"},
			InUse:     true,
			Users:     []camdet.Process{{PID: 1234, Name: "zoom", Node: "/dev/video0"}},
		}},
		FullVisibility: true,
	}
}

func envMap(env []string) map[string]string {
	m := make(map[string]string, len(env))
	for _, e := range env {
		if i := strings.IndexByte(e, '='); i >= 0 {
			m[e[:i]] = e[i+1:]
		}
	}
	return m
}

func TestAnyInUse(t *testing.T) {
	if anyInUse(idleResult()) {
		t.Fatal("idle result should not be in use")
	}
	if !anyInUse(inUseResult()) {
		t.Fatal("in-use result should be in use")
	}
	if anyInUse(&camdet.Result{}) {
		t.Fatal("a result with no cameras should not be in use")
	}
}

func TestEventFor(t *testing.T) {
	if got := eventFor(true); got != "on" {
		t.Fatalf("eventFor(true) = %q, want \"on\"", got)
	}
	if got := eventFor(false); got != "off" {
		t.Fatalf("eventFor(false) = %q, want \"off\"", got)
	}
}

func TestHookEnvOn(t *testing.T) {
	now := time.Date(2026, 9, 10, 12, 0, 0, 0, time.UTC)
	got := envMap(hookEnv("on", inUseResult(), now))

	want := map[string]string{
		"CAMDET_EVENT":          "on",
		"CAMDET_TIMESTAMP":      "2026-09-10T12:00:00Z",
		"CAMDET_CAMERAS_IN_USE": "1",
		"CAMDET_CAMERA_NAMES":   "HD Pro Webcam C920",
		"CAMDET_CAMERA_IDS":     "046d:082d",
		"CAMDET_USERS":          "zoom(1234)",
	}
	for k, v := range want {
		if got[k] != v {
			t.Errorf("%s = %q, want %q", k, got[k], v)
		}
	}
}

func TestHookEnvOffHasEmptyLists(t *testing.T) {
	now := time.Date(2026, 9, 10, 12, 0, 0, 0, time.UTC)
	got := envMap(hookEnv("off", idleResult(), now))

	if got["CAMDET_EVENT"] != "off" {
		t.Errorf("CAMDET_EVENT = %q, want \"off\"", got["CAMDET_EVENT"])
	}
	if got["CAMDET_CAMERAS_IN_USE"] != "0" {
		t.Errorf("CAMDET_CAMERAS_IN_USE = %q, want \"0\"", got["CAMDET_CAMERAS_IN_USE"])
	}
	if got["CAMDET_CAMERA_NAMES"] != "" {
		t.Errorf("CAMDET_CAMERA_NAMES = %q, want empty", got["CAMDET_CAMERA_NAMES"])
	}
	if got["CAMDET_USERS"] != "" {
		t.Errorf("CAMDET_USERS = %q, want empty", got["CAMDET_USERS"])
	}
}

// TestWatchFiresOnStartupThenOnEdges verifies fire-on-startup semantics and that
// the hook fires only on state changes thereafter, not on every poll.
func TestWatchFiresOnStartupThenOnEdges(t *testing.T) {
	results := []*camdet.Result{idleResult(), inUseResult(), inUseResult(), idleResult()}
	index := 0
	detect := func() (*camdet.Result, error) {
		r := results[index]
		index++
		return r, nil
	}

	var events []string
	w := &watcher{
		detect: detect,
		onEvent: func(_ context.Context, event string, _ *camdet.Result) {
			events = append(events, event)
		},
	}

	tick := make(chan time.Time)
	ctx, cancel := context.WithCancel(context.Background())
	done := make(chan error, 1)
	go func() { done <- w.run(ctx, tick) }()

	tick <- time.Now() // idle -> in use: fires "on"
	tick <- time.Now() // in use -> in use: no change
	tick <- time.Now() // in use -> idle: fires "off"
	cancel()
	if err := <-done; err != nil {
		t.Fatalf("run returned error: %v", err)
	}

	want := []string{"off", "on", "off"} // startup(off), edge(on), edge(off)
	if strings.Join(events, ",") != strings.Join(want, ",") {
		t.Fatalf("events = %v, want %v", events, want)
	}
}

func TestWatchStartupDetectErrorIsFatal(t *testing.T) {
	detect := func() (*camdet.Result, error) { return nil, fmt.Errorf("boom") }
	w := &watcher{
		detect:  detect,
		onEvent: func(context.Context, string, *camdet.Result) {},
	}
	if err := w.run(context.Background(), make(chan time.Time)); err == nil {
		t.Fatal("expected fatal error when startup detect fails")
	}
}

func TestRunScriptReceivesArgAndEnv(t *testing.T) {
	dir := t.TempDir()
	outFile := filepath.Join(dir, "out.txt")
	script := filepath.Join(dir, "hook.sh")
	body := "#!/bin/sh\n{ echo \"arg=$1\"; echo \"event=$CAMDET_EVENT\"; echo \"names=$CAMDET_CAMERA_NAMES\"; } > " + outFile + "\n"
	if err := os.WriteFile(script, []byte(body), 0o755); err != nil {
		t.Fatal(err)
	}

	now := time.Date(2026, 9, 10, 12, 0, 0, 0, time.UTC)
	if err := runScript(context.Background(), script, 5*time.Second, "on", inUseResult(), now); err != nil {
		t.Fatalf("runScript: %v", err)
	}

	data, err := os.ReadFile(outFile)
	if err != nil {
		t.Fatal(err)
	}
	out := string(data)
	for _, want := range []string{"arg=on", "event=on", "names=HD Pro Webcam C920"} {
		if !strings.Contains(out, want) {
			t.Errorf("hook output missing %q; got:\n%s", want, out)
		}
	}
}

func TestRunScriptTimeoutIsEnforced(t *testing.T) {
	dir := t.TempDir()
	script := filepath.Join(dir, "hang.sh")
	if err := os.WriteFile(script, []byte("#!/bin/sh\nsleep 10\n"), 0o755); err != nil {
		t.Fatal(err)
	}

	start := time.Now()
	err := runScript(context.Background(), script, 200*time.Millisecond, "on", inUseResult(), time.Now())
	if err == nil {
		t.Fatal("expected a timeout error from a hanging hook")
	}
	if elapsed := time.Since(start); elapsed > 3*time.Second {
		t.Fatalf("timeout not enforced; hook ran for %s", elapsed)
	}
}

func TestRunScriptNonZeroExitIsError(t *testing.T) {
	dir := t.TempDir()
	script := filepath.Join(dir, "fail.sh")
	if err := os.WriteFile(script, []byte("#!/bin/sh\nexit 3\n"), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := runScript(context.Background(), script, 5*time.Second, "off", idleResult(), time.Now()); err == nil {
		t.Fatal("expected an error when the hook exits non-zero")
	}
}

func TestLogTransitionJSONIsValid(t *testing.T) {
	var buf bytes.Buffer
	now := time.Date(2026, 9, 10, 12, 0, 0, 0, time.UTC)
	logTransition(&buf, "on", inUseResult(), now, true)

	var rec map[string]any
	if err := json.Unmarshal(buf.Bytes(), &rec); err != nil {
		t.Fatalf("transition JSON is invalid: %v\n%s", err, buf.String())
	}
	if rec["event"] != "on" {
		t.Errorf("event = %v, want \"on\"", rec["event"])
	}
	if rec["timestamp"] != "2026-09-10T12:00:00Z" {
		t.Errorf("timestamp = %v", rec["timestamp"])
	}
}

